/* One focused feature workspace for the connected quest / art / passport loop. */
let featureOpen=false,featureView='art',featureQuestion=null,featureGalleryOpen=false,gallerySelection=null;
const featureRoot=document.getElementById('featureWorkspace');
const legacyRoots=['regions','vocabulary','nav','nova','lens','guideControls','musicControls','toolControls'];
function showEntity(id,visible){const el=$(id);if(!el)return;el.setAttribute('visible',visible);if(el.object3D)el.object3D.visible=visible}
function openAdventure(view='art'){window.globiquest.globePatch?.disarm?.();window.globiquest.closeKaleidoscope?.();view='art';window.globiquest.stopHandLab?.();window.globiquest.closePortal?.();window.globiquest.closeTravel?.();window.globiquest.closeScope?.();featureOpen=true;$('notifications').setAttribute('position','0 4.7 -2');featureView=view;releaseLens();legacyRoots.forEach(id=>showEntity(id,false));showEntity('environment',true);showEntity('mapRoot',true);showEntity('featureWorkspace',true);showEntity('artGallery',false);renderFeature();window.globiquest.refreshWorkspace?.();window.globiquest.presentTaskPanel?.('featureWorkspace')}
function closeAdventure(gallery=false){window.globiquest.artPlay?.stop();featureOpen=false;$('notifications').setAttribute('position','0 4.7 -2');legacyRoots.forEach(id=>showEntity(id,true));showEntity('environment',true);showEntity('mapRoot',true);showEntity('featureWorkspace',false);showEntity('artGallery',gallery);featureGalleryOpen=gallery;if(gallery)buildArtGallery();renderReward();status('Choose Art studio to keep creating, or explore the globe.');window.globiquest.refreshWorkspace?.()}
function featureButton(title,x,y,action,width=1.15,accent=false,height=.3){const button=panel(featureRoot,{title,x,y,width,height,z:.045,font:Math.min(90,Math.round(height/width*1024*.42)),align:'center',accent,action});button.setAttribute?.('aria-label',title);button.setAttribute?.('data-activate-on-press','true');return button}
function renderFeature(){legacyRoots.forEach(id=>{if(id!=='nav')showEntity(id,false)});dispose(featureRoot);const backing=panel(featureRoot,{width:4.02,height:3.7,y:-.04,z:-.05,color:'#fffef9'});window.GlobiquestPanelInput.bind(backing,1,1,[]);const region=regions[state.region];featureRoot.dataset.inlineMaximize='true';featureRoot.__refreshMaximize=renderArtPanelSizeButton;const artHeader=panel(featureRoot,{kicker:'PINCH HEADER TO MOVE',title:'⠿ Art Studio',width:2.15,height:.4,x:-.83,y:1.47,font:43});window.GlobiquestPanelInput.bind(artHeader,1,1,[{x:0,y:0,w:1,h:1,label:'Move Art Studio',drag:true}]);renderArtPanelSizeButton();featureButton('Close',1.56,1.56,()=>window.globiquest.dismissPanel?.(featureRoot),.65,false,.23);featureButton('← Move left',-.65,-1.69,()=>featureRoot.components?.['xr-nav-drag']?.nudge(-1,0),1.15,false,.22);featureButton('Move right →',.65,-1.69,()=>featureRoot.components?.['xr-nav-drag']?.nudge(1,0),1.15,false,.22);renderArtStudio()}
function renderArtPanelSizeButton(){const old=featureRoot.querySelector('[data-panel-maximize]');if(old){const m=old.getObject3D('mesh');m?.material?.map?.dispose();m?.material?.dispose();old.remove()}const b=featureButton(scene.components?.['xr-view']?.maximized?.el===featureRoot?'Restore':'Maximize',.72,1.56,()=>window.globiquest.maximizePanel?.(featureRoot),.9,false,.23);b.setAttribute('data-panel-maximize','true')}
function renderMissions(){const region=regions[state.region],p=adventure.progress(region),r=adventure.record(region);const tasks=[['visit','Explore a destination',()=>openAdventure('explore')],['words','Collect two travel words',()=>openAdventure('lesson')],['recall','Recall a useful travel phrase',()=>openAdventure('quiz')],['art','Paint and save a travel postcard',()=>openAdventure('art')]];tasks.forEach(([key,text,action],i)=>panel(featureRoot,{title:(p[key]?'✓  ':'○  ')+text,width:3.8,height:.34,y:.54-i*.43,font:35,action,accent:false}));panel(featureRoot,{title:r.stamped?'Passport stamp earned! A new path is open.':Object.values(p).filter(Boolean).length+' / 4 missions complete · Finish all four to earn a stamp',width:3.8,height:.28,y:-1.22,font:27,align:'center'});}
function renderQuestExplore(){panel(featureRoot,{title:'Choose a place to visit',width:3.8,height:.29,y:.6,font:33});placesInRegion().forEach(({d,i},n)=>panel(featureRoot,{title:d[0]+', '+d[1],body:d[6],width:3.8,height:.5,y:.1-n*.58,font:42,action:()=>{choosePlace(i);adventure.award(regions[state.region],'visits',String(i));openAdventure('quest');notify('Destination discovered · '+d[0])}}));featureButton('← Region',-1,-1.13,()=>{chooseRegion((state.region+5)%6);openAdventure('explore')},1.3);featureButton('Region →',1,-1.13,()=>{chooseRegion((state.region+1)%6);openAdventure('explore')},1.3)}
function renderLesson(){const w=words[state.language][state.word];panel(featureRoot,{kicker:'TRAVEL WORD '+(state.word+1)+' / 4',title:w[0],body:w[1]+'  ·  '+w[2],width:3.8,height:.9,y:.23,font:w[0].length>20?47:73});featureButton('♫ Listen',-1.25,-.5,()=>say(w[0]),1.15);featureButton('＋ Collect',0,-.5,()=>{saveWord();renderFeature()},1.15,true);featureButton('Next →',1.25,-.5,()=>{nextWord();renderFeature()},1.15);featureButton(languageNames[state.language]+' ↻',0,-.95,()=>{changeLanguage();renderFeature()},2.4);panel(featureRoot,{title:adventure.record(regions[state.region]).words.length+' collected here · Collect at least two distinct words',width:3.8,height:.25,y:-1.22,font:26,align:'center'})}
function makeQuestion(){const index=Math.floor(Math.random()*4),indices=[index,...[0,1,2,3].filter(v=>v!==index).sort(()=>Math.random()-.5).slice(0,2)];for(let i=indices.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[indices[i],indices[j]]=[indices[j],indices[i]]}return{index,language:state.language,indices,solved:false}}
function renderQuiz(){if(!featureQuestion||featureQuestion.language!==state.language)featureQuestion=makeQuestion();const q=featureQuestion,w=words[q.language][q.index];panel(featureRoot,{title:'What does this phrase mean?',body:w[0]+'  /  '+w[1],width:3.8,height:.55,y:.42,font:37});featureButton('♫ Hear it again',0,-.02,()=>say(w[0]),2);if(q.solved){panel(featureRoot,{title:'Correct! '+w[2],width:3.8,height:.4,y:-.55,font:40,align:'center'});featureButton('Continue mission →',0,-1.08,()=>openAdventure('quest'),2.6,true);return}q.indices.forEach((i,n)=>featureButton(words[q.language][i][2],0,-.4-n*.33,()=>{if(i===q.index){q.solved=true;adventure.award(regions[state.region],'recalls',q.language+':'+q.index);renderFeature();notify('Correct · recall challenge completed')}else notify('Try again. Listen to Nova for a clue.')},3.7,false,.27))}
function renderArtStudio(){const region=regions[state.region];if(window.globiquest.artPlay?.jellySession){const art=window.globiquest.artPlay;panel(featureRoot,{title:'Jelly friends',body:art.airActive?'Draw one loop, then release to hatch a friend.':'Drawing is stopped. Start another when you are ready.',width:3.6,height:.7,y:.45,font:48,align:'center'});featureButton(art.airActive?'Stop drawing':'Draw another jelly',0,-.12,()=>art.airActive?art.stop():art.armJelly(),2.8,false,.42);featureButton('Undo',-.92,-.72,()=>art.undo(),1.7,false,.38);featureButton('Clear all',.92,-.72,()=>art.clear(),1.7,false,.38);featureButton('Back to canvas',0,-1.28,()=>art.finishJelly(),2.8,false,.35);return}panel(featureRoot,{title:'Draw a squiggle',width:3.8,height:.24,y:.64,font:27,align:'center'});const canvas=entity('a-plane',{id:'paintingSurface',width:2.65,height:1.66,position:'-.45 -.3 .02',material:'shader:flat; side:double','art-canvas':''},featureRoot);canvas.classList.add('interactive');canvas.addEventListener('loaded',()=>window.GlobiquestPanelInput.prepare(canvas),{once:true});if(canvas.hasLoaded)window.GlobiquestPanelInput.prepare(canvas);const loadSaved=()=>{const saved=adventure.art(region);if(saved&&!window.globiquest.artPlay?.suppressSavedArt)canvas.components['art-canvas']?.load(saved.data)};canvas.addEventListener('loaded',loadSaved,{once:true});if(canvas.hasLoaded)loadSaved();const tools=()=>canvas.components['art-canvas'];const palette=['#527d75','#89a7bd','#cda4ad','#e5bb7b','#806c9b','#d78562','#344455','#fffdf6'];palette.forEach((color,i)=>{const swatch=entity('a-circle',{radius:.07,position:`${-1.53+i*.3} -1.29 .04`,material:`shader:flat; color:${color}; side:double`},featureRoot);swatch.classList.add('interactive');window.GlobiquestPanelInput.bind(swatch,1,1,[{x:0,y:0,w:1,h:1,label:'Brush colour '+(i+1),action:()=>{const t=tools();t?.up?.();if(t)t.color=color;window.globiquest.artPlay.airColor=color;status('Brush colour changed')}}])});[['Brush','brush'],['Sun','sun'],['Peaks','mountain'],['Tree','tree']].forEach(([title,mode],i)=>featureButton(title,1.25+(i%2)*.49,.34-Math.floor(i/2)*.3,()=>{if(tools())tools().mode=mode},.44,false,.24));featureButton('Bring to life',1.49,-.29,()=>window.globiquest.artPlay?.bringToLife(tools()),.94,true,.24);featureButton('Loop to jelly',1.49,-.57,()=>{if(window.globiquest.artPlay?.startJelly(tools()))renderFeature()},.94,true,.28);featureButton('Clear 3D',1.49,-.86,()=>{window.globiquest.artPlay?.clear();renderFeature()},.94,false,.25);featureButton('Undo',1.25,-1.15,()=>window.globiquest.artPlay?.airActive?window.globiquest.artPlay.undo():tools()?.undo(),.44,false,.23);featureButton('Clear',1.74,-1.15,()=>tools()?.clear(),.44,false,.23);featureButton('Save',1.25,-1.44,()=>{const t=tools();if(!t?.strokes){notify('Draw something before saving.');return}try{adventure.saveArt(region,t.canvas.toDataURL('image/webp',.92),destinations[state.place][0],[],state.language);notify('Artwork saved on this device.')}catch(e){notify(e.message)}},.44,true,.24);featureButton('PNG',1.74,-1.44,()=>{const t=tools();if(!t?.strokes){notify('Draw something before exporting.');return}const link=document.createElement('a');link.download='Globiquest-Scope-'+destinations[state.place][0]+'-art.png';link.href=t.canvas.toDataURL('image/png');link.click()},.44,false,.24);featureButton('Brush size',-.45,-1.48,()=>{const t=tools();if(t){t.size=t.size===12?24:t.size===24?6:12;status('Brush size: '+t.size)}},.94,false,.23);status('Art Studio · Draw a squiggle, bring it to life, or paint in the air.')}
function renderPassport(){regions.forEach((region,i)=>{const saved=adventure.art(region);panel(featureRoot,{kicker:saved?'ARTWORK SAVED':'CREATE HERE',title:region,body:saved?saved.city:'Explore a place and make something.',width:1.8,height:.54,x:(i%2-.5)*1.98,y:.36-Math.floor(i/2)*.6,font:33,accent:!!saved,action:()=>{chooseRegion(i);openAdventure('art')}})});panel(featureRoot,{title:'Your artwork saves on this device',width:3.8,height:.23,y:-1.27,font:25,align:'center'})}
function renderGallery(){const entries=regions.map(region=>({region,art:adventure.art(region)})).filter(x=>x.art);if(!entries.length){panel(featureRoot,{title:'Your gallery begins with one postcard.',body:'Open Art studio, paint something, then save it here.',width:3.8,height:.8,y:.05,font:42});return}entries.slice(0,6).forEach(({region,art},i)=>{const x=(i%3-1)*1.25,y=.36-Math.floor(i/3)*.92;const image=entity('a-plane',{width:1.13,height:.7,position:`${x} ${y} .03`,src:art.data,material:'shader:flat; side:double'},featureRoot);image.classList.add('interactive');image.addEventListener('click',()=>{gallerySelection=region;openAdventure('memory')});panel(featureRoot,{title:art.city+(art.phrases?.length?' · '+art.phrases.length+' phrases':' / '+region),width:1.17,height:.18,x,y:y-.46,font:22,align:'center'})});featureButton('Display beside the tiny world',0,-1.23,()=>closeAdventure(true),3.5,true,.25)}
function buildArtGallery(){const root=$('artGallery');dispose(root);regions.forEach((region,i)=>{const art=adventure.art(region);if(!art)return;const x=(i%2)*1.5,y=1.6-Math.floor(i/2)*1.1;panel(root,{title:art.city,width:1.35,height:.2,x,y:y-.54,font:27,align:'center'});entity('a-plane',{width:1.3,height:.81,position:`${x} ${y} .02`,src:art.data,material:'shader:flat; side:double'},root)})}
function renderReward(){const root=$('questReward');root.replaceChildren();if(!adventure.record(regions[state.region]).stamped)return;for(let i=0;i<11;i++)entity('a-box',{position:`0 ${.12+Math.sin(i/10*Math.PI)*.13} ${.85+i*.15}`,width:.42,height:.045,depth:.14,color:'#ddc6a8'},root);entity('a-octahedron',{position:'0 .72 2.3',radius:.13,color:'#e6c789',animation:'property:rotation; to:0 360 0; loop:true; dur:12000; easing:linear'},root)}
adventure.onChange=({earned,region})=>{renderReward();if(featureOpen&&featureView!=='art')renderFeature();if(earned){notify('Passport stamp earned in '+region+' · new path unlocked!');window.globiquest.celebrate?.()}};
window.globiquest.refreshArtStudio=()=>{if(featureOpen&&featureView==='art')renderFeature()};window.globiquest.openAdventure=openAdventure;window.globiquest.closeAdventure=closeAdventure;window.globiquest.adventure=adventure;
$('play').onclick=()=>openAdventure();

if(typeof MutationObserver!=='undefined'){const observer=new MutationObserver(()=>{if(featureOpen)legacyRoots.forEach(id=>showEntity(id,false))});legacyRoots.forEach(id=>{const el=$(id);if(el)observer.observe(el,{childList:true,subtree:true})})}

if(scene.hasLoaded)renderReward();else scene.addEventListener('loaded',renderReward,{once:true});

function renderMemoryCard(){const region=gallerySelection||regions[state.region],art=adventure.art(region);if(!art){renderGallery();return}entity('a-plane',{width:2,height:1.25,position:'-.88 .12 .03',src:art.data,material:'shader:flat; side:double'},featureRoot);panel(featureRoot,{title:art.city+' · '+region,width:2,height:.25,x:-.88,y:-.72,font:31,align:'center'});const phrases=art.phrases||[];if(phrases.length){phrases.slice(0,4).forEach((phrase,i)=>{const [native,...meaning]=phrase.split(' — ');panel(featureRoot,{title:native,body:meaning.join(' — '),width:1.62,height:.35,x:1.1,y:.48-i*.4,font:30,action:()=>say(native,art.language||state.language)})})}else panel(featureRoot,{title:'Add a café memory',body:'Finish the café rehearsal and save your art again to keep its useful phrases.',width:1.62,height:1.1,x:1.1,y:0,font:36});featureButton('Edit postcard',-.95,-1.2,()=>{chooseRegion(regions.indexOf(region));openAdventure('art')},1.8,false,.27);featureButton('Replay café',1,-1.2,()=>{chooseRegion(regions.indexOf(region));if(art.language&&words[art.language])state.language=art.language;startCafe()},1.8,true,.27);featureButton('Display on island',0,-1.53,()=>window.globiquest.displayPostcard?.(region),2.5,false,.23)}
